    chairs = image_patch.find("chair")
    tables = image_patch.find("table")

    if not chairs or not tables:
        return image_patch

    table_depths = [(t, t.compute_depth()) for t in tables]
    table_depths.sort(key=lambda x: x[1])
    closest_table = table_depths[0][0]

    chairs_next_to_table = [c for c in chairs if abs(c.horizontal_center - closest_table.horizontal_center) < 20]

    if not chairs_next_to_table:
        return image_patch

    chairs_behind_chair = []
    for chair in chairs_next_to_table:
        behind = [c for c in chairs if c.compute_depth() > chair.compute_depth()]
        chairs_behind_chair.extend(behind)

    if chairs_behind_chair:
        return min(chairs_behind_chair, key=lambda c: abs(c.horizontal_center - closest_table.horizontal_center))

    return chairs_next_to_table[0]

