    image_patch = ImagePatch(image)
    tables = image_patch.find("table")
    windows = image_patch.find("window")

    if not tables or not windows:
        return image_patch

    min_distance = float('inf')
    nearest_table = None

    for table in tables:
        for window in windows:
            dist = distance(table, window)
            if dist < min_distance:
                min_distance = dist
                nearest_table = table

    return nearest_table

