modern_c2_ds.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    stove_patches = image_patch.find("stove")
    window_patches = image_patch.find("window")

    if not stove_patches:
        return image_patch
    if not window_patches:
        return stove_patches[0]

    stove_center_x = (stove_patches[0].left + stove_patches[0].right) / 2
    window_center_x = (window_patches[0].left + window_patches[0].right) / 2

    if abs(stove_center_x - window_center_x) < max(stove_patches[0].width, window_patches[0].width):
        return stove_patches[0]

    return image_patch

