modern_c4_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    handbag_patches = image_patch.find("handbag")
    lady_patches = image_patch.find("lady")

    if not handbag_patches or not lady_patches:
        return image_patch

    black_handbags = [h for h in handbag_patches if h.verify_property("handbag", "black")]

    if not black_handbags:
        return image_patch

    lady_handbag_pairs = [(l, h) for l in lady_patches for h in black_handbags if h.overlaps_with(l.left, l.lower, l.right, l.upper)]

    if not lady_handbag_pairs:
        return image_patch

    return lady_handbag_pairs[0][1]

